import { scaleLinear } from '@visx/scale';

export const getSegmentWidth = (
  value: number,
  min: number,
  max: number,
  containerWidth: number,
): number => {
  if (value === 0) {
    return value;
  }

  /**
   * Parsing the value to use the min as a starting point
   * Useful for negative min values
   */
  const valueWithStartingPoint = value + min;

  if (min === max) {
    return value >= max ? containerWidth : 0;
  }

  const segmentScale = scaleLinear({
    domain: [min, max],
    range: [0, containerWidth],
    clamp: true,
  });

  return segmentScale(valueWithStartingPoint);
};
